import Foundation

/// Learned "is this fix right?" model (logistic regression over 12 facts about a fix).
/// Generated by `tools/train learn` from real typo data. Don't edit by hand; retrain instead.
/// Facts, in order: slip cost, cost per letter, lead over runner-up, word frequency, fits left word, fits right word, length, candidates in reach, macOS knows it, capitalised, contraction, known stem + ending.
enum FixGate {
    /// Bold fixes more of your messy words; Careful only fixes when it's very sure
    enum Mode: String { case bold, careful }
    static var mode: Mode = .bold
    static var threshold: Double { mode == .bold ? boldThreshold : carefulThreshold }
    static var forceOff = false   // training/testing: use the hand-written rules instead
    static var isTrained: Bool { !weights.isEmpty && !forceOff }

    static let boldThreshold = 0.73
    static let carefulThreshold = 0.83
    static let mean: [Double] = [0.624069, 0.108903, 2.647495, 7.980288, 1.598531, 1.454258, 6.752300, 3.542830, 0.244400, 0.033700, 0.005000, 0.432602]
    static let scale: [Double] = [0.317103, 0.068648, 0.780317, 1.253151, 1.493427, 1.496000, 2.899232, 1.833590, 0.429731, 0.180456, 0.070534, 1.751412]
    static let weights: [Double] = [-0.961802, -0.275926, 0.740108, 0.837512, 0.288030, 0.403726, 0.675885, 0.119180, -0.585839, -0.156545, 0.015035, -0.412762]
    static let bias = 2.719064

    /// Chance (0-1) that fixing to the best candidate is right
    static func probability(_ x: [Double]) -> Double {
        var z = bias
        for i in 0..<weights.count { z += weights[i] * (x[i] - mean[i]) / scale[i] }
        return 1 / (1 + exp(-z))
    }
}
